<?php
declare(strict_types=1);
require __DIR__.'/harness.php';require __DIR__.'/database.php';require __DIR__.'/services-fixture.php';
use Hostider\Core\Database\Migrator;use Hostider\Core\Id;use Hostider\Core\Http\HttpError;use Hostider\Core\Security\{AccessGrant,Principal};use Hostider\Services\{Engine,Worker,Reconciliation};use Hostider\Hosting\Pools;
$db=integrationDb();(new Migrator($db,dirname(__DIR__).'/migrations'))->migrate();
function unknownFixture($db,string $scenario='TIMEOUT_AFTER_CREATE'): array
{
    $f=serviceFixture($db);$pool=(new Pools($db,$f['config']))->configure($f['product']);$engine=new Engine($db,$f['config']);$service=$engine->discover($f['order']['id'],$f['actor'],Id::uuid())[0];$operation=$engine->repository->find($service,lock:false)['current_operation_id'];(new Worker($db,$f['config']))->once($f['actor'],$operation,$scenario);
    $staff=new Principal('scoped-service-operator',['services.reconcile'],staff:true,mfa:true,expiresAt:time()+3600,verifiedAt:time(),grants:[new AccessGrant('services.reconcile',[$f['customer']],[$service])]);$reconciliation=new Reconciliation($db,$f['config']);return array_replace($f,compact('pool','engine','service','operation','staff','reconciliation'));
}
test('F3-D found UNKNOWN attaches existing mock resource without second create or ledger write',function()use($db): void{
    $f=unknownFixture($db);$before=$db->execute('SELECT COUNT(*) FROM finance_journals')->fetchColumn();$proof=$f['reconciliation']->inspect($f['service'],$f['customer'],$f['staff'],Id::uuid());same(true,$proof['found']);$result=$f['reconciliation']->resolve($f['service'],$f['customer'],$proof['inspection_id'],$f['staff'],Id::uuid());same('ACTIVE',$result['status']);same('UNKNOWN',$db->execute('SELECT status FROM svc_operations WHERE id=?',[$f['operation']])->fetchColumn());same(1,(int)$db->execute('SELECT COUNT(*) FROM mock_hosting_accounts WHERE service_id=?',[$f['service']])->fetchColumn());same(1,(int)$db->execute('SELECT COUNT(*) FROM svc_resources WHERE service_id=?',[$f['service']])->fetchColumn());same($before,$db->execute('SELECT COUNT(*) FROM finance_journals')->fetchColumn());same(409,raises(HttpError::class,fn()=>$f['reconciliation']->resolve($f['service'],$f['customer'],$proof['inspection_id'],$f['staff'],Id::uuid()))->status);
});
test('F3-D not-found remains manual review and never retries or releases unknown capacity',function()use($db): void{
    $f=unknownFixture($db,'TIMEOUT_BEFORE_CREATE');$proof=$f['reconciliation']->inspect($f['service'],$f['customer'],$f['staff'],Id::uuid());same(false,$proof['found']);same('MANUAL_REVIEW_NO_RETRY',$proof['decision']);same(409,raises(HttpError::class,fn()=>$f['reconciliation']->resolve($f['service'],$f['customer'],$proof['inspection_id'],$f['staff'],Id::uuid()))->status);same('UNKNOWN',$f['engine']->repository->find($f['service'],lock:false)['status']);same(false,(new Worker($db,$f['config']))->once($f['actor'],$f['operation']));same('HELD',$db->execute('SELECT status FROM hosting_reservations WHERE operation_id=?',[$f['operation']])->fetchColumn());same(0,(int)$db->execute('SELECT COUNT(*) FROM mock_hosting_accounts WHERE service_id=?',[$f['service']])->fetchColumn());
});
test('F3-D scope step-up and actor-bound evidence deny unauthorized reconciliation',function()use($db): void{
    $f=unknownFixture($db);same(403,raises(HttpError::class,fn()=>$f['reconciliation']->inspect($f['service'],$f['customer'],$f['actor'],Id::uuid()))->status);same(403,raises(HttpError::class,fn()=>$f['reconciliation']->inspect($f['service'],Id::uuid(),$f['staff'],Id::uuid()))->status);$stale=new Principal('scoped-service-operator',['services.reconcile'],staff:true,mfa:true,expiresAt:time()+3600,verifiedAt:time()-301,grants:$f['staff']->grants);same(403,raises(HttpError::class,fn()=>$f['reconciliation']->inspect($f['service'],$f['customer'],$stale,Id::uuid()))->status);
    $proof=$f['reconciliation']->inspect($f['service'],$f['customer'],$f['staff'],Id::uuid());$other=new Principal('other-operator',['services.reconcile'],staff:true,mfa:true,expiresAt:time()+3600,verifiedAt:time(),grants:$f['staff']->grants);same(403,raises(HttpError::class,fn()=>$f['reconciliation']->resolve($f['service'],$f['customer'],$proof['inspection_id'],$other,Id::uuid()))->status);raises(PDOException::class,fn()=>$db->execute('UPDATE svc_inspections SET found=FALSE WHERE id=?',[$proof['inspection_id']]));
});
test('F3-D source refund blocks attach and injected audit failure rolls back all financial-neutral activation',function()use($db): void{
    $f=unknownFixture($db);$proof=$f['reconciliation']->inspect($f['service'],$f['customer'],$f['staff'],Id::uuid());$db->execute("UPDATE orders SET refund_status='FULL' WHERE id=?",[$f['order']['id']]);same(409,raises(HttpError::class,fn()=>$f['reconciliation']->resolve($f['service'],$f['customer'],$proof['inspection_id'],$f['staff'],Id::uuid()))->status);same(0,(int)$db->execute('SELECT COUNT(*) FROM svc_resources WHERE service_id=?',[$f['service']])->fetchColumn());
    $f=unknownFixture($db);$proof=$f['reconciliation']->inspect($f['service'],$f['customer'],$f['staff'],Id::uuid());$db->execute("CREATE TRIGGER test_f3_activation_failure BEFORE INSERT ON svc_events FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Injected service event failure'");try{raises(PDOException::class,fn()=>$f['reconciliation']->resolve($f['service'],$f['customer'],$proof['inspection_id'],$f['staff'],Id::uuid()));}finally{$db->execute('DROP TRIGGER test_f3_activation_failure');}same('UNKNOWN',$f['engine']->repository->find($f['service'],lock:false)['status']);same(0,(int)$db->execute('SELECT COUNT(*) FROM svc_resources WHERE service_id=?',[$f['service']])->fetchColumn());same(0,(int)$db->execute('SELECT COUNT(*) FROM svc_resolutions WHERE service_id=?',[$f['service']])->fetchColumn());same('ACTIVE',$f['reconciliation']->resolve($f['service'],$f['customer'],$proof['inspection_id'],$f['staff'],Id::uuid())['status']);
});
runTests();
